import{a as e,c as t,i as n,t as r}from"./app-B8uz0aqq.js";var i=JSON.parse(`{"path":"/32-Coding_and_Contribution_Guidelines.html","title":"Coding & Contribution Guidelines","lang":"en-US","frontmatter":{},"filePathRelative":"32-Coding_and_Contribution_Guidelines.md","git":{"createdTime":1765123328000,"updatedTime":1765123328000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"}]}}`),a={name:`32-Coding_and_Contribution_Guidelines.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="coding-contribution-guidelines" tabindex="-1"><a class="header-anchor" href="#coding-contribution-guidelines"><span>Coding &amp; Contribution Guidelines</span></a></h1><blockquote><p>目的：为 Apollo MMORPG 服务器项目制定统一的编码规范、代码审核流程、分支策略与提交要求，确保多人协作时保持高质量与一致性。</p></blockquote><h2 id="_1-分支与版本管理" tabindex="-1"><a class="header-anchor" href="#_1-分支与版本管理"><span>1. 分支与版本管理</span></a></h2><h3 id="_1-1-主分支策略" tabindex="-1"><a class="header-anchor" href="#_1-1-主分支策略"><span>1.1 主分支策略</span></a></h3><ul><li><code>main</code>：稳定分支，始终可发布。所有功能 feature 合入前必须经过 CI/测试。</li><li><code>develop</code>（可选）：需要频繁迭代时，可在其上合并 feature，定期回合 <code>main</code>。</li><li>Feature 命名：<code>feature/&lt;module&gt;-&lt;short-desc&gt;</code>；Bugfix 命名：<code>fix/&lt;issue-id&gt;-&lt;desc&gt;</code>。</li></ul><h3 id="_1-2-提交流程" tabindex="-1"><a class="header-anchor" href="#_1-2-提交流程"><span>1.2 提交流程</span></a></h3><ol><li>创建/更新 feature 分支。</li><li>编写代码 + 单元测试。</li><li>进行自测（UT、必要的集成测试）。</li><li>提交 PR -&gt; 触发 CI（lint/UT/构建）。</li><li>通过评审后合并回 <code>main</code>/<code>develop</code>。</li></ol><h2 id="_2-编码规范" tabindex="-1"><a class="header-anchor" href="#_2-编码规范"><span>2. 编码规范</span></a></h2><h3 id="_2-1-c-风格" tabindex="-1"><a class="header-anchor" href="#_2-1-c-风格"><span>2.1 C++ 风格</span></a></h3><ul><li>采用 Google C++ Style 的变体： <ul><li>文件名 <code>snake_case</code>，类名 <code>PascalCase</code>，函数 <code>CamelCase</code>，变量 <code>snake_case</code>。</li><li>使用 <code>#pragma once</code>，优先 <code>std::unique_ptr</code>/<code>std::shared_ptr</code>。</li><li>禁止裸 <code>new/delete</code>，使用 RAII 或内存池。</li><li>常量使用 <code>constexpr</code>。</li><li>命名空间 <code>apollo::&lt;module&gt;</code> 结构。</li></ul></li><li>引入 clang-format（配置文件 <code>.clang-format</code>）与 clang-tidy 检查。</li><li>注重 noexcept/const correctness；接口使用 <code>std::span/std::string_view</code> 等现代类型。</li></ul><h3 id="_2-2-c-unity" tabindex="-1"><a class="header-anchor" href="#_2-2-c-unity"><span>2.2 C#/Unity</span></a></h3><ul><li>采用 Unity 官方 C# Style（PascalCase 类/方法，camelCase 字段）。</li><li>使用 <code>async/await</code> 管理异步；避免 <code>Thread.Sleep</code>。</li><li>所有 SDK API 提供 XML 文档注释。</li></ul><h3 id="_2-3-配置与脚本" tabindex="-1"><a class="header-anchor" href="#_2-3-配置与脚本"><span>2.3 配置与脚本</span></a></h3><ul><li>YAML/JSON 使用 2 空格缩进。</li><li>Lua 脚本遵循 “需要注释”“小函数” 原则，禁止全局变量污染。</li><li>Proto 文件按字段编号分段，注释包含中文/英文说明。</li></ul><h2 id="_3-文档要求" tabindex="-1"><a class="header-anchor" href="#_3-文档要求"><span>3. 文档要求</span></a></h2><ul><li>每个模块必须有设计文档（Markdown）并保持更新。</li><li>PR 如修改协议/配置，需同步更新文档和生成文件。</li><li>README/CHANGELOG 保持最新，记录重要变更。</li></ul><h2 id="_4-测试与质量门禁" tabindex="-1"><a class="header-anchor" href="#_4-测试与质量门禁"><span>4. 测试与质量门禁</span></a></h2><ul><li>提交必须通过 CI 的 UT/格式检查。</li><li>新功能需附带测试用例；重大缺陷修复需增加回归测试。</li><li>性能敏感模块在 PR 中附带基准数据或压测结果（若有影响）。</li></ul><h2 id="_5-代码评审" tabindex="-1"><a class="header-anchor" href="#_5-代码评审"><span>5. 代码评审</span></a></h2><ul><li>至少 1 名 reviewer（核心模块 2 名）。</li><li>重点检查：线程安全、内存管理、异常处理、协议兼容性。</li><li>PR 尺寸建议 &lt; 500 行改动，超出需拆分或提前沟通。</li><li>评审完成后统一 squash/merge（保留清晰历史）。</li></ul><h2 id="_6-issue-与任务管理" tabindex="-1"><a class="header-anchor" href="#_6-issue-与任务管理"><span>6. Issue 与任务管理</span></a></h2><ul><li>使用 Jira/GitHub Issues；每个 Issue 包含：背景、需求、验收标准。</li><li>PR 需关联 Issue ID。</li><li>任务标签：<code>architecture</code>, <code>network</code>, <code>data</code>, <code>sdk</code>, <code>ops</code>, <code>bug</code> 等。</li></ul><h2 id="_7-风险与安全" tabindex="-1"><a class="header-anchor" href="#_7-风险与安全"><span>7. 风险与安全</span></a></h2><ul><li>禁止将密钥/密码写入代码库；测试用假数据也需标注。</li><li>第三方依赖需在清单中登记版本，进行安全扫描（SBOM）。</li><li>引入新依赖需评估许可证兼容性。</li></ul><h2 id="_8-release-与标签" tabindex="-1"><a class="header-anchor" href="#_8-release-与标签"><span>8. Release 与标签</span></a></h2><ul><li>每次发布在 Git 上打 tag <code>vX.Y.Z</code>，附 Release Note（功能、新增文档、兼容性）。</li><li>对应 SDK/服务器版本需写入 manifest，供部署/客户端参考。</li></ul><h2 id="_9-故障处理" tabindex="-1"><a class="header-anchor" href="#_9-故障处理"><span>9. 故障处理</span></a></h2><ul><li>线上问题需记录在 Incident 文档中（时间线、根因、修复、预防）。</li><li>提交 post-mortem 后再关闭 Issue。</li></ul><h2 id="_10-roadmap" tabindex="-1"><a class="header-anchor" href="#_10-roadmap"><span>10. Roadmap</span></a></h2><ol><li>完成 <code>.clang-format</code>、<code>.clang-tidy</code>、<code>.editorconfig</code> 配置提交。</li><li>建立 CI 质量门禁（格式/UT/构建）。</li><li>文档模板与 PR 模板入库（<code>.github/PULL_REQUEST_TEMPLATE.md</code>）。</li><li>定期 Code Review 培训/分享，提升团队一致性。</li></ol><hr><p>此指南为开发者提供统一协作规范，应随团队实践持续完善。***</p>`,32)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};